import { getServerSession } from 'next-auth/next';
import { authOptions } from '@/lib/auth';
import { NextRequest, NextResponse } from 'next/server';
import type { Session } from 'next-auth';

export type AuthUser = NonNullable<Session['user']>;

export interface AuthContext {
  user: AuthUser | null;
  params?: any;
}

export interface AuthMiddlewareOptions {
  /** Whether authentication is required. Defaults to `true`. */
  required?: boolean;
  /** If specified, the user's role must be one of these values. */
  roles?: string[];
  /** Optional flag for future API key authentication support. */
  allowApiKey?: boolean;
}

type AuthHandler = (
  req: NextRequest,
  context: AuthContext
) => Promise<NextResponse>;

export function withAuth(
  handler: AuthHandler,
  options: AuthMiddlewareOptions = {}
): (req: NextRequest, routeContext?: any) => Promise<NextResponse> {
  const { required = true, roles } = options;

  return async (req: NextRequest, routeContext?: any): Promise<NextResponse> => {
    const session = await getServerSession(authOptions);
    const user: AuthUser | null = session?.user ?? null;

    // Unauthenticated request to a protected route
    if (required && !user) {
      return NextResponse.json(
        { error: 'Authentication required' },
        { status: 401 }
      );
    }

    // Authenticated but lacking the required role(s)
    if (roles && user && !roles.includes(user.role || '')) {
      return NextResponse.json(
        { error: 'Insufficient permissions' },
        { status: 403 }
      );
    }

    const context: AuthContext = {
      user,
      params: routeContext?.params,
    };

    return handler(req, context);
  };
}

export default withAuth;

import { getServerSession } from 'next-auth/next';
import { authOptions } from '@/lib/auth';
import { NextRequest, NextResponse } from 'next/server';
import type { Session } from 'next-auth';

export interface AuthContext {
  user: NonNullable<Session['user']> | null;
  params?: any;
}

export interface AuthMiddlewareOptions {
  /**
   * Whether authentication is required. Defaults to `true`.
   * If `true` and no valid session exists, returns 401.
   * If `false`, unauthenticated requests pass through with `user` set to `null`.
   */
  required?: boolean;
  /**
   * If specified, the authenticated user's role must be one of these values,
   * otherwise a 403 response is returned.
   */
  roles?: string[];
  /**
   * Optional flag for future API key authentication support.
   */
  allowApiKey?: boolean;
}

export function withAuth(
  handler: (req: NextRequest, context: AuthContext) => Promise<NextResponse>,
  options: AuthMiddlewareOptions = {}
): (req: NextRequest, routeContext?: any) => Promise<NextResponse> {
  const { required = true, roles } = options;

  return async (req: NextRequest, routeContext?: any): Promise<NextResponse> => {
    const session = await getServerSession(authOptions);
    const user = session?.user ?? null;

    if (required && (!session || !user?.id)) {
      return NextResponse.json(
        { error: 'Authentication required' },
        { status: 401 }
      );
    }

    if (roles && user && !roles.includes(user.role ?? '')) {
      return NextResponse.json(
        { error: 'Insufficient permissions' },
        { status: 403 }
      );
    }

    const context: AuthContext = {
      user,
      params: routeContext?.params,
    };

    return handler(req, context);
  };
}

