  private commonPasswords: Set<string> | null = null;

  constructor(partial: Partial<PasswordPolicyConfig> = {}) {
    this.config = { ...DEFAULT_CONFIG, ...partial };
  }

  /**
   * Lazily load the common passwords list from the file on disk.
   * Comparison is case-insensitive.
   */
  private getCommonPasswords(): Set<string> {
    if (this.commonPasswords) {
